package com.adib.maintenance;
import android.view.*;import android.widget.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import java.lang.reflect.*;import java.time.Duration;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk={24,28,35}) public class WorkScreenFeaturesTest{
@After public void cleanup(){RuntimeEnvironment.getApplication().getSharedPreferences("calendar-scale",0).edit().clear().commit();}
@Test public void undoNeverCommitsAndDelayIsFiveSeconds(){MainActivity a=Robolectric.buildActivity(MainActivity.class).get();int[] writes={0};CompletionUndo.schedule(a,"t",()->writes[0]++);Shadows.shadowOf(android.os.Looper.getMainLooper()).idleFor(Duration.ofMillis(4999));assertEquals(0,writes[0]);assertNotNull(a.getWindow().getDecorView().findViewWithTag("completion-undo:t"));CompletionUndo.cancel(a,"t");Shadows.shadowOf(android.os.Looper.getMainLooper()).idleFor(Duration.ofSeconds(1));assertEquals(0,writes[0]);CompletionUndo.schedule(a,"t",()->writes[0]++);CompletionUndo.schedule(a,"t",()->writes[0]+=100);Shadows.shadowOf(android.os.Looper.getMainLooper()).idleFor(Duration.ofSeconds(5));assertEquals(1,writes[0]);assertNull(a.getWindow().getDecorView().findViewWithTag("completion-undo:t"));}
@Test public void undoUsesEditorWindow(){MainActivity a=Robolectric.buildActivity(MainActivity.class).setup().get();android.app.Dialog d=new android.app.Dialog(a);d.show();CompletionUndo.surface(a,d.getWindow().getDecorView());CompletionUndo.schedule(a,"editor",()->{});assertNotNull(d.getWindow().getDecorView().findViewWithTag("completion-undo:editor"));assertNull(a.getWindow().getDecorView().findViewWithTag("completion-undo:editor"));CompletionUndo.cancel(a,"editor");CompletionUndo.clearSurface(a,d.getWindow().getDecorView());d.dismiss();}
@Test public void scaleIsPerTimedViewAndChangesCanvasHeight(){TaskCalendarActivity a=Robolectric.buildActivity(TaskCalendarActivity.class).get();a.mode="week";a.phone=new CalendarPhoneUi(a);a.phone.render();a.phone.setHour(96);assertEquals(96,a.phone.hour);assertEquals(a.dp(24*96),a.root.findViewWithTag("calendar-hour-grid").getLayoutParams().height);a.mode="three";a.phone.content();assertEquals(64,a.phone.hour);a.phone.setHour(112);a.mode="week";a.phone.content();assertEquals(96,a.phone.hour);a.phone.setHour(1000);assertEquals(160,a.phone.hour);a.mode="month";a.phone.content();a.phone.setHour(40);assertEquals(64,a.phone.hour);}
@Test public void matrixShowsIndependentChecksAndCenteredFab()throws Exception{JSONObject old=AccountSession.user;AccountSession.user=new JSONObject().put("role","admin");try{MainActivity a=Robolectric.buildActivity(MainActivity.class).get();set(a,"personalTasks",new JSONArray().put(new JSONObject().put("id","task").put("title","Sensoru yoxla")));set(a,"screen","list");set(a,"mode","matrix");Method m=MainActivity.class.getDeclaredMethod("render");m.setAccessible(true);m.invoke(a);View root=(View)get(a,"root");assertNotNull(root.findViewWithTag("matrix-check:task"));Button add=(Button)root.findViewWithTag("task-view-add");assertNotNull(add);assertEquals("",add.getText().toString());assertNotNull(add.getForeground());}finally{AccountSession.user=old;}}
@Test public void workScreenPreservesFieldsAndNotes()throws Exception{MainActivity a=Robolectric.buildActivity(MainActivity.class).get();LinearLayout form=new LinearLayout(a),chat=new LinearLayout(a);EditText title=new EditText(a),estimate=new EditText(a),date=new EditText(a),notes=new EditText(a);title.setText("Sensoru yoxla");estimate.setText("75");date.setText("2026-10-13T09:00:00");notes.setText("Kontaktları yoxla");form.addView(title);form.addView(estimate);form.addView(date);form.addView(notes);TaskDetailTabs tabs=new TaskDetailTabs(a,form,title,notes,null,chat,false,"Avadanlıq");tabs.workScreen(a,new JSONObject().put("id","t"),null,null,estimate,date,null,null,notes,()->{});assertEquals(View.VISIBLE,tabs.findViewWithTag("task-work-screen").getVisibility());assertEquals(View.GONE,tabs.findViewWithTag("task-pane:1").getVisibility());assertSame(form,estimate.getParent());tabs.findViewWithTag("work-all-properties").performClick();assertEquals(View.VISIBLE,tabs.findViewWithTag("task-pane:1").getVisibility());estimate.setText("90");notes.setText("Yeni qeyd");tabs.showWork();assertEquals("90",estimate.getText().toString());assertEquals("Yeni qeyd",((TextView)tabs.findViewWithTag("work-description-preview")).getText().toString());}
void set(Object a,String n,Object v)throws Exception{Field f=a.getClass().getDeclaredField(n);f.setAccessible(true);f.set(a,v);}Object get(Object a,String n)throws Exception{Field f=a.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(a);}
}
